    rtrials = params.trialid{rcond}; % right hit trials
    rdata = squeeze(obj.trialdat(:,thisunit,rtrials)); % single trial data for right hit trials
    ltrials = params.trialid{lcond}; % left hit trials
    ldata = squeeze(obj.trialdat(:,thisunit,ltrials)); % single trial data for left hit trials

    rmu = mean(rdata,2); % psth
    rse = std(rdata,[],2)./sqrt(numel(rtrials)); % std err
    lmu = mean(ldata,2); % psth
    lse = std(ldata,[],2)./sqrt(numel(ltrials)); % std err

    shadedErrorBar(obj.time,rmu,rse,{'Color',colors.rhit,'LineWidth',2},0.3,ax);
    shadedErrorBar(obj.time,lmu,lse,{'Color',colors.lhit,'LineWidth',2},0.3,ax);
    cluid = params.cluid(thisunit);
    quality = obj.clu{params.probe}(cluid).quality;
    title(['Unit ' num2str(cluid) ', ' quality])
    xlabel(['Time from ' lower(params.alignEvent) ' (s)'])
    ylabel('spks/sec')
    plotEventTimes(ax,evtimes)
end

function idx = findClusters(qualityList, qualities)
% find idx where qualityList contains at least one of the patterns in
% qualities

% remove leading/trailing spaces
% also check if each entry in qualityList is a string/char, if not, change
% it
for i = 1:numel(qualityList)
    if ~ischar(qualityList{i}) && ~isstring(qualityList{i})
        qualityList{i} = '';
    end
end
qualityList = strtrim(qualityList);

if any(strcmpi(qualities,'all')) || strcmpi(qualities{1},'all')
    idx = find(~ismember(qualityList,'garbage') & ~ismember(qualityList,'gabrga') & ~ismember(qualityList,'noisy') & ~ismember(qualityList,'real?'));
%     idx = 1:numel(qualityList);
    return
end

% handle unlabeled cluster qualities
for i = 1:numel(qualityList)
    if isempty(qualityList{i})
        qualityList(i) = {'nan'};
    end
%     qualityList(i) = lower(qualityList(i));
end

[~,mask] = patternMatchCellArray(qualityList, qualities, 'any');

idx = find(mask);
end % findClusters

